// CRIMSON NIGHT — COMPREHENSIVE GITHUB ASSET BUNDLE (IMAGES + 3D CHESS + AUDIO)
// Upload this file (crimson-night-images.js) to your GitHub repo alongside crimson-night.html
// ============================================================================
// CRIMSON NIGHT & NEO — SUPPLEMENTARY GITHUB IMAGE BUNDLE (crimson-night-images.js)
window._CN_IMG = {
  neo: 'data:image/png;base64,',
  logo: 'data:image/jpeg;base64,',
  concept: 'data:image/jpeg;base64,',
  merch: 'data:image/webp;base64,',
  malakor: 'data:image/jpeg;base64,',
  vespera: 'data:image/jpeg;base64,',
  ossuary: 'data:image/jpeg;base64,',
  kaelenBM: 'data:image/jpeg;base64,',
  kaelenCU: 'data:image/jpeg;base64,',
  halo: 'data:image/jpeg;base64,'
};
window.CRIMSON_NIGHT_IMAGES = {
  'assets/neo-official-logo.png': window._CN_IMG.neo,
  'assets/neo-logo-transparent.png': window._CN_IMG.neo,
  'assets/crimson-night-official-logo.png': window._CN_IMG.logo,
  'assets/crimson-night-logo-transparent.png': window._CN_IMG.logo,
  'assets/crimson-night-character-concept.png': window._CN_IMG.concept,
  'assets/crimson-night-merchandise-collector.webp': window._CN_IMG.merch,
  'assets/malakor-weeping-archon.jpg': window._CN_IMG.malakor,
  'assets/lady-vespera-npc.jpg': window._CN_IMG.vespera,
  'assets/ossuary-amalgam.jpg': window._CN_IMG.ossuary,
  'assets/trailer-kaelen-bloodmoon.jpg': window._CN_IMG.kaelenBM,
  'assets/trailer-kaelen-closeup.jpg': window._CN_IMG.kaelenCU,
  'assets/trailer-scene-1-eclipse.jpg': window._CN_IMG.kaelenBM,
  'assets/trailer-scene-2-kaelen-combat.jpg': window._CN_IMG.ossuary,
  'assets/trailer-scene-4-halo-crossover.jpg': window._CN_IMG.halo,
  'assets/halo-crimson-collab.jpg': window._CN_IMG.halo,
  'assets/crimson-night-art.jpg': window._CN_IMG.kaelenBM
};
(function applyCrimsonNightImages() {
  const bank = window.CRIMSON_NIGHT_IMAGES;
  if (!bank) return;
  function resolveAssetUri(src) {
    if (!src) return null;
    if (bank[src]) return bank[src];
    const idx = src.indexOf('assets/');
    if (idx !== -1) {
      const rel = src.substring(idx);
      if (bank[rel]) return bank[rel];
    }
    return null;
  }
  function hydrateAllImages() {
    document.querySelectorAll('img').forEach(img => {
      const rawSrc = img.getAttribute('src') || '';
      const dataUri = resolveAssetUri(rawSrc);
      if (dataUri && img.src !== dataUri) {
        img.src = dataUri;
      }
    });
    if (typeof trailerImages !== 'undefined' && typeof trailerAssetSources !== 'undefined') {
      Object.keys(trailerAssetSources).forEach(key => {
        const dataUri = resolveAssetUri(trailerAssetSources[key]);
        if (dataUri && trailerImages[key]) trailerImages[key].src = dataUri;
      });
    }
    if (typeof ostTracks !== 'undefined' && Array.isArray(ostTracks)) {
      ostTracks.forEach(t => {
        const dataUri = resolveAssetUri(t.cover);
        if (dataUri) t.cover = dataUri;
      });
    }
  }
  function wrapLightbox() {
    if (typeof window.openLightbox === 'function' && !window.openLightbox._wrappedByBundle) {
      const orig = window.openLightbox;
      const wrapped = function(src, title, desc) {
        return orig(resolveAssetUri(src) || src, title, desc);
      };
      wrapped._wrappedByBundle = true;
      window.openLightbox = wrapped;
    }
  }
  hydrateAllImages();
  wrapLightbox();
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => { hydrateAllImages(); wrapLightbox(); });
  }
  window.addEventListener('load', () => { hydrateAllImages(); wrapLightbox(); });
})();

window.GRIM_CHESS_B64 = '';

// ============================================================================
// 3D CHESS MINI-GAME & AUDIO ASSET HYDRATION ENGINE
// ============================================================================
(function() {
  function hydrateChessGame() {
    const frame = document.getElementById('minigame-iframe');
    if (!frame || !window.GRIM_CHESS_B64) return;
    try {
      if (!frame.srcdoc || frame.srcdoc.length < 500) {
        const binStr = atob(window.GRIM_CHESS_B64);
        const len = binStr.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binStr.charCodeAt(i);
        }
        const decodedHtml = new TextDecoder('utf-8').decode(bytes);
        window.GRIM_CHESS_HTML = decodedHtml;
        frame.srcdoc = decodedHtml;

        // Ensure 'Open Full Window' button works on GitHub even without separate grim-chess-3d.html file
        const fullWinBtn = document.querySelector('a[href="grim-chess-3d.html"]');
        if (fullWinBtn && !fullWinBtn._blobAttached) {
          fullWinBtn._blobAttached = true;
          fullWinBtn.addEventListener('click', function(e) {
            fetch('grim-chess-3d.html', { method: 'HEAD' }).then(res => {
              if (!res.ok) {
                e.preventDefault();
                const blob = new Blob([decodedHtml], { type: 'text/html;charset=utf-8' });
                const url = URL.createObjectURL(blob);
                window.open(url, '_blank');
              }
            }).catch(() => {
              e.preventDefault();
              const blob = new Blob([decodedHtml], { type: 'text/html;charset=utf-8' });
              const url = URL.createObjectURL(blob);
              window.open(url, '_blank');
            });
          });
        }
      }
    } catch (err) {
      console.warn('Hydrate Chess Mini-game notice:', err);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', hydrateChessGame);
  } else {
    hydrateChessGame();
  }
  window.addEventListener('load', hydrateChessGame);
})();
